fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    // k is 1-based indexing, so the element to remove is at zero-based index k-1
    let index_to_remove = k - 1;
    // Create a new vector with capacity for n - 1 elements
    let mut new_list = Vec::with_capacity(list.len() - 1);

    // Extend with elements before the removed index
    new_list.extend_from_slice(&list[..index_to_remove]);
    // Extend with elements after the removed index
    new_list.extend_from_slice(&list[index_to_remove + 1..]);

    new_list
}